import{_ as p,B as n,o,c as h,a8 as l,d as u,w as c,f as t,E as a,af as m,a as i}from"./chunks/framework.CNIpabDg.js";const x=JSON.parse('{"title":"Graphics","description":"The Graphics module hosts LVGL 9.6 and exposes window/display/input services through an explicitly owned manager.","frontmatter":{"layout":"doc","docType":"explanation","description":"The Graphics module hosts LVGL 9.6 and exposes window/display/input services through an explicitly owned manager."},"headers":[],"relativePath":"explanation/architecture/subsystems/graphics.md","filePath":"explanation/architecture/subsystems/graphics.md","lastUpdated":1792926318000}'),g={name:"explanation/architecture/subsystems/graphics.md"};function k(f,e,y,b,v,w){const d=n("Mermaid"),r=n("HostReference"),s=n("CodeReference");return o(),h("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792926318000"},[e[9]||(e[9]=l('<h1 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h1><p>The Graphics module hosts LVGL 9.6 and exposes window/display/input services through an explicitly owned manager.</p><h2 id="role-in-system" tabindex="-1">Role in system <a class="header-anchor" href="#role-in-system" aria-label="Permalink to &quot;Role in system&quot;">​</a></h2><ul><li>Owns LVGL initialization and timer handler loop integration.</li><li>Bridges platform screen/input character devices into LVGL display/input objects.</li><li>Provides window lifecycle APIs and event retrieval for application runtimes.</li></ul><h2 id="responsibilities-and-boundaries" tabindex="-1">Responsibilities and boundaries <a class="header-anchor" href="#responsibilities-and-boundaries" aria-label="Permalink to &quot;Responsibilities and boundaries&quot;">​</a></h2><p><strong>In scope</strong></p><ul><li>Manager construction and LVGL runtime lifecycle.</li><li>Display/input device registration and runtime polling.</li><li>Window creation, enumeration, focus/maximize operations, and close requests.</li><li>Theme initialization and updates.</li></ul><p><strong>Out of scope</strong></p><ul><li>Full safe Rust wrapper coverage for all LVGL symbols.</li><li>Application-level UI architecture decisions.</li></ul><h2 id="internal-architecture" tabindex="-1">Internal architecture <a class="header-anchor" href="#internal-architecture" aria-label="Permalink to &quot;Internal architecture&quot;">​</a></h2><ul><li>Owned <code>Manager</code> returned by <code>graphics::initialize(time_manager, ...)</code>, with: <ul><li><code>inner: RwLock&lt;Inner&gt;</code> storing display/input vectors and window parent object,</li><li><code>global_lock: Mutex&lt;()&gt;</code> used to serialize LVGL-critical sections.</li></ul></li><li>Initialization calls <code>lv_init</code> and registers the supplied time manager for the C tick callback. <code>graphics::set_ffi_manager</code> installs a static graphics reference for callbacks that cannot carry Rust references.</li><li><code>Manager::loop</code> drives <code>lv_timer_handler()</code> and periodic display resize checks.</li><li><code>Window</code> wraps <code>lv_obj_t*</code>, stores user data queue, and maps LVGL events into Xila event types.</li></ul>',11)),(o(),u(m,null,{default:c(()=>[a(d,{id:"mermaid-106",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Clients%40%7B%20shape%3A%20processes%2C%20label%3A%20%22Executables%20%2F%20modules%22%20%7D%0A%20%20%20%20Init%5Bgraphics%3A%3Ainitialize(...)%5D%0A%20%20%20%20Manager%5BExplicit%20Graphics%20Manager%5D%0A%20%20%20%20LoopTask%5BGraphics%20loop%20task%5D%0A%20%20%20%20LVGL%5BLVGL%20runtime%5D%0A%20%20%20%20ScreenDev%5BScreen%20DirectCharacterDevice%5D%0A%20%20%20%20InputDev%5BInput%20DirectCharacterDevice(s)%5D%0A%20%20%20%20TimeMod%5BSupplied%20time%20manager%5D%0A%0A%20%20%20%20Clients%20--%3E%7Cwindow%2Ftheme%2Finput%20APIs%7C%20Manager%0A%20%20%20%20Init%20--%3E%20Manager%0A%20%20%20%20LoopTask%20--%3E%7CManager%3A%3Aloop()%7C%20LVGL%0A%20%20%20%20Manager%20--%3E%7Cdisplay%20flush%7C%20ScreenDev%0A%20%20%20%20Manager%20--%3E%7Cinput%20poll%7C%20InputDev%0A%20%20%20%20TimeMod%20--%3E%7Ctick%20callback%7C%20LVGL%0A%20%20%20%20Manager%20--%3E%7Cglobal%20lock%7C%20LVGL%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=l(`<h2 id="lifecycle-and-execution-model" tabindex="-1">Lifecycle and execution model <a class="header-anchor" href="#lifecycle-and-execution-model" aria-label="Permalink to &quot;Lifecycle and execution model&quot;">​</a></h2><ol><li>Initialize <a href="/explanation/architecture/subsystems/time.html">Time</a> first.</li><li>Initialize graphics with the time manager, screen/input devices, and buffer configuration; retain the returned manager and register it with <code>set_ffi_manager</code> where needed.</li><li>Spawn graphics loop task calling <code>Manager::loop(...)</code>.</li><li>Applications create windows and process queued events.</li><li>Optional runtime updates: add inputs, update theme, close/maximize windows.</li></ol><h2 id="data-control-flow" tabindex="-1">Data/control flow <a class="header-anchor" href="#data-control-flow" aria-label="Permalink to &quot;Data/control flow&quot;">​</a></h2><ul><li>Input devices -&gt; LVGL event callbacks -&gt; per-window event queues.</li><li>Manager loop polls LVGL timers and triggers display maintenance.</li><li>Host bindings may call graphics APIs under manager lock (WASM path).</li></ul><h2 id="concurrency-and-synchronization-model" tabindex="-1">Concurrency and synchronization model <a class="header-anchor" href="#concurrency-and-synchronization-model" aria-label="Permalink to &quot;Concurrency and synchronization model&quot;">​</a></h2><ul><li>LVGL-sensitive operations are protected by manager-level mutex lock.</li><li>Metadata collections use <code>RwLock</code> for async read/write access.</li><li>Window/user-data pointers rely on explicit ownership conventions and <code>from_raw</code>/<code>into_raw</code> usage discipline.</li></ul><h2 id="dependency-model" tabindex="-1">Dependency model <a class="header-anchor" href="#dependency-model" aria-label="Permalink to &quot;Dependency model&quot;">​</a></h2><ul><li>Depends on <a href="/explanation/architecture/subsystems/time.html">Time</a> for tick callback.</li><li>Interacts with <a href="/explanation/architecture/executables/bindings.html">Bindings</a> and VM runtime in WASM host path.</li><li>Uses platform <code>DirectCharacterDevice</code> implementations for concrete display/input IO.</li></ul><h2 id="failure-semantics-and-recovery-behavior" tabindex="-1">Failure semantics and recovery behavior <a class="header-anchor" href="#failure-semantics-and-recovery-behavior" aria-label="Permalink to &quot;Failure semantics and recovery behavior&quot;">​</a></h2><ul><li>Initialization failures panic in current manager construction path.</li><li>Runtime operations return typed <code>graphics::Error</code> for invalid window identifiers and object failures.</li><li>Event queue and object pointer misuse can surface as runtime failures if ownership rules are violated.</li></ul><h2 id="runtime-inspection-and-synthetic-input" tabindex="-1">Runtime inspection and synthetic input <a class="header-anchor" href="#runtime-inspection-and-synthetic-input" aria-label="Permalink to &quot;Runtime inspection and synthetic input&quot;">​</a></h2><p>The manager installs <strong>graphics-owned virtual pointer and keypad devices</strong> even without a physical input device. This enables diagnostics and UI automation through the same LVGL runtime as normal applications.</p><ul><li><code>get_resolution()</code> reads the active display resolution. <code>inject_pointer_move(point)</code> rejects negative positions and coordinates beyond the right or bottom edge.</li><li><code>inject_pointer_button(state)</code>, <code>inject_key(key, state)</code> and <code>inject_text(text)</code> enqueue input events; text injection is limited to <strong>printable ASCII</strong>.</li><li><code>inspect_ui_tree(max_elements, max_depth)</code> returns a bounded tree snapshot with a truncation indicator. Its element IDs are <strong>snapshot-local indexes</strong>, not persistent LVGL object handles.</li><li><code>capture_screen()</code> captures the active screen into an owned RGBA8888 snapshot. Inspection and capture report <code>NotAvailable</code> when their required UI/display state is missing.</li></ul><p>These operations acquire the graphics lock. Callers should neither retain raw LVGL pointers across calls nor reuse snapshot indexes after a new snapshot.</p><h3 id="example-inspect-the-ui" tabindex="-1">Example: inspect the UI <a class="header-anchor" href="#example-inspect-the-ui" aria-label="Permalink to &quot;Example: inspect the UI&quot;">​</a></h3><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolution </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> graphics_manager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get_resolution</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.await?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> snapshot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> graphics_manager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inspect_ui_tree</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.await?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> screenshot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> graphics_manager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">capture_screen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.await?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>This snippet assumes an initialized <code>graphics_manager</code> with an active display. The graphics loop must still be scheduled to process LVGL timers and queued input. See Rustdoc for the concrete snapshot types.</p><h2 id="build-time-graphics-and-font-assets" tabindex="-1">Build-time graphics and font assets <a class="header-anchor" href="#build-time-graphics-and-font-assets" aria-label="Permalink to &quot;Build-time graphics and font assets&quot;">​</a></h2><p>The runtime graphics crate explicitly enables <code>lvgl_rust_sys/build-lvgl</code> to compile the native LVGL C archive, while guest/bindgen-only dependencies need not compile LVGL. The graphics <code>build.rs</code> uses the selected locale and fallback to generate font C sources and compile them into a separate <code>font_assets</code> static archive in Cargo <code>OUT_DIR</code>. Font-only changes can therefore rebuild the font archive without rebuilding LVGL C sources. The old standalone <code>fonts_generator</code> executable and eager <code>generate-fonts</code> task have been removed. This separation landed in Core #505; #506 restored the runtime C linkage and corrected upstream bindgen include paths.</p><p>Since Core #508, the Rust font build cache generates four deduplicated Latin range variants and archives each font/variant in a separate native object. <code>src/fonts.rs</code> selects the active six symbols at compile time using link aliases: the font archive may hold 24 objects, but <strong>unselected font variants are not linked</strong>. Chinese builds additionally subset Source Han Sans SC to glyphs occurring in localized catalog values, avoiding the entire CJK range (Core #456). The cache accounts for input fonts, converter/tool versions, locale ranges and generator options, and regenerates missing or corrupted results. Use <code>mise run test:fonts</code> to check cache and link behavior; there is no runtime font registry.</p><p>The generated fonts are compile-time assets, not dynamically loaded fonts. Node.js and <code>lv_font_conv</code> (installed via <code>mise run deps:npm</code>) are required during generation. The graphics lifetime regression previously seen after #506 subsequently passed in Core #515&#39;s <code>mise run test:workspace</code> validation. This does not establish hardware-target correctness or runtime memory use.</p><h2 id="extension-points" tabindex="-1">Extension points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension points&quot;">​</a></h2><ul><li>Add additional input devices at runtime.</li><li>Extend window/theme APIs and higher-level widget wrappers.</li><li>Expand bindings/codegen coverage for broader LVGL surface.</li></ul><h2 id="known-limitations-and-trade-offs" tabindex="-1">Known limitations and trade-offs <a class="header-anchor" href="#known-limitations-and-trade-offs" aria-label="Permalink to &quot;Known limitations and trade-offs&quot;">​</a></h2><ul><li>Significant portions remain close to LVGL C-style pointer semantics.</li><li>Global lock simplifies safety but can become a bottleneck under heavy UI call contention.</li><li>LVGL and callback registration remain process-global; explicit manager ownership does not establish support for multiple independent LVGL runtimes.</li><li>Event kinds track LVGL 9.6 numeric codes. Guest event transport preserves numeric codes, including close requests, instead of treating unknown values as valid Rust enum variants.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Stable module contract:</strong> Graphics provides a global service surface for display/input lifecycle, window management, and event delivery to executables through typed APIs.</li><li><strong>Current implementation details:</strong> An owned manager coordinates LVGL state, protects critical sections with its mutex, and stores runtime collections in <code>RwLock</code>-protected metadata; tick/FFI callbacks retain registered static references.</li><li><strong>Compatibility note:</strong> Consumers should rely on API behavior and documented error semantics, not on internal lock composition, pointer wrapping strategy, or exact LVGL wiring details.</li></ul><h2 id="references-see-also" tabindex="-1">References / See also <a class="header-anchor" href="#references-see-also" aria-label="Permalink to &quot;References / See also&quot;">​</a></h2>`,28)),i("ul",null,[i("li",null,[a(r,{crate:"graphics"})]),i("li",null,[a(r,{crate:"graphics",kind:"struct",symbol:"Manager"}),e[1]||(e[1]=t(" — runtime API.",-1))]),i("li",null,[a(s,{path:"subsystems/graphics/src/manager.rs"}),e[2]||(e[2]=t(" — lifecycle, inspection and synthetic input.",-1))]),i("li",null,[a(s,{path:"subsystems/graphics/src/window.rs"}),e[3]||(e[3]=t(" — window ownership and events.",-1))]),i("li",null,[a(s,{path:"subsystems/graphics/build.rs"}),e[4]||(e[4]=t(" and ",-1)),a(s,{path:"subsystems/graphics/build/fonts.rs"}),e[5]||(e[5]=t(" — locale-aware font generation, caching and archive build.",-1))]),i("li",null,[a(s,{path:"subsystems/graphics/src/fonts.rs"}),e[6]||(e[6]=t(" — compile-time font selection.",-1))]),i("li",null,[a(s,{path:"subsystems/graphics/fonts/README.md"}),e[7]||(e[7]=t(" — catalog-specific Chinese glyph subsetting.",-1))]),e[8]||(e[8]=i("li",null,[i("a",{href:"/explanation/architecture/libraries/file_system.html"},"File system")],-1))])])}const L=p(g,[["render",k]]);export{x as __pageData,L as default};
